// Des: Tests account book: missing file, limits, id rules
// Flo: scratch folder > write user-acct.json > load > pick > errors for bad books
// I/O: scratch dir (no real data) > pass or fail (no leaks)
// Run: zig build test -Dfile=ut-acct-book-test.zig
// ===================================================================
const std = @import("std"); const book = @import("ut-acct-book.zig");
fn dirOf(tmp: *std.testing.TmpDir, aren: std.mem.Allocator) ![]u8 { return std.fmt.allocPrint(aren, ".zig-cache/tmp/{s}", .{tmp.sub_path}); }
fn put(tmp: *std.testing.TmpDir, aren: std.mem.Allocator, data: []const u8) ![]u8 { const dir = try dirOf(tmp, aren); try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = try std.fmt.allocPrint(aren, "{s}/user-acct.json", .{dir}), .data = data }); return dir; }
test "a missing file, folder or empty list is one account main" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); const b1 = try book.loadBook(al, std.testing.io, try dirOf(&tmp, al), 5); try std.testing.expect(!b1.filez); try std.testing.expectEqualStrings("main", b1.main); try std.testing.expectEqual(@as(usize, 1), b1.accs.len); const b2 = try book.loadBook(al, std.testing.io, "", 5); try std.testing.expectEqual(@as(usize, 1), b2.accs.len); const dir = try put(&tmp, al, "{\"accs\":[]}"); const b3 = try book.loadBook(al, std.testing.io, dir, 5); try std.testing.expect(b3.filez); try std.testing.expectEqualStrings("main", b3.main); }
test "several accounts: pick by id, main defaults to the first, label phone lang and caps percent are read" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); const dir = try put(&tmp, al, "{\"v\":1,\"accs\":[{\"id\":\"shop1\",\"label\":\"Shop\",\"phone\":\"0912345678\"},{\"id\":\"home\",\"lang\":\"en\",\"scal\":40}]}"); const bk = try book.loadBook(al, std.testing.io, dir, 5); try std.testing.expectEqual(@as(usize, 2), bk.accs.len); try std.testing.expectEqualStrings("shop1", bk.main); try std.testing.expectEqualStrings("Shop", book.pick(bk, "").?.label); try std.testing.expectEqual(@as(u32, 40), book.pick(bk, "home").?.scal); try std.testing.expectEqualStrings("en", book.pick(bk, "home").?.lang); try std.testing.expect(book.pick(bk, "nope") == null); }
test "bad books are rejected: repeated id, bad id, too many, unknown main, caps percent out of range, broken JSON" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); const bads = [_][]const u8{ "{\"accs\":[{\"id\":\"a\"},{\"id\":\"a\"}]}", "{\"accs\":[{\"id\":\"A b\"}]}", "{\"accs\":[{\"id\":\"a\"},{\"id\":\"b\"},{\"id\":\"c\"}]}", "{\"main\":\"zz\",\"accs\":[{\"id\":\"a\"}]}", "{\"accs\":[{\"id\":\"a\",\"scal\":0}]}", "{\"accs\":[{\"id\":\"a\",\"scal\":101}]}", "oops" }; for (bads) |txt| { const dir = try put(&tmp, al, txt); try std.testing.expectError(error.BadConfig, book.loadBook(al, std.testing.io, dir, 2)); } }
test "id rules and masked phone" { try std.testing.expect(book.idOk("shop-1")); try std.testing.expect(!book.idOk("")); try std.testing.expect(!book.idOk("Shop")); try std.testing.expect(!book.idOk("../x")); try std.testing.expect(!book.idOk("this-id-is-way-too-long")); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); try std.testing.expectEqualStrings("***678", try book.maskPhone(aren.allocator(), "0912345678")); try std.testing.expectEqualStrings("-", try book.maskPhone(aren.allocator(), "")); try std.testing.expectEqualStrings("***12", try book.maskPhone(aren.allocator(), "12")); }
